<script setup>
import {ref,computed,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import Icon from '../components/Icon.vue'
import AppDropdown from '../components/AppDropdown.vue'
import WireframeCanvas from '../components/WireframeCanvas.vue'
const route=useRoute(),router=useRouter(),index=ref([]),selected=ref(String(route.query.screen||'LT-01')),data=ref(null),search=ref(''),group=ref(''),device=ref(''),mode=ref('styled'),loading=ref(true),error=ref(''),zoom=ref(.65)
const current=computed(()=>index.value.find(s=>s.screenCode===selected.value)),filtered=computed(()=>index.value.filter(s=>(!group.value||s.screenCode.startsWith(group.value))&&(!device.value||(device.value==='mobile'?s.width<600:s.width>=600))&&(!search.value||(s.title+' '+s.screenCode).toLowerCase().includes(search.value.toLowerCase()))))
let request=0
async function load(){const id=++request;loading.value=true;error.value='';try{const r=await fetch('/references/'+selected.value+'.json');if(!r.ok)throw Error('Không tải được dữ liệu');const json=await r.json();if(id!==request)return;data.value=json;zoom.value=json.canvas.width<600?.8:.65;router.replace({query:{screen:selected.value}})}catch(e){if(id===request)error.value=e.message}finally{if(id===request)loading.value=false}}
fetch('/references/index.json').then(r=>r.json()).then(r=>{index.value=r;if(!r.some(s=>s.screenCode===selected.value))selected.value='LT-01';load()}).catch(()=>{error.value='Không tải được danh mục wireframe.';loading.value=false})
watch(selected,load)
const size=computed(()=>({width:(current.value?.width||1280)*zoom.value+'px',height:((current.value?.height||800)-40)*zoom.value+'px'}))
</script>
<template><div class="reference-page"><aside class="reference-sidebar"><RouterLink to="/" class="back-link"><Icon name="back" :size="16"/>Về website</RouterLink><h1>Đối chiếu wireframe</h1><p class="muted">140 màn hình gốc · 5 nhóm</p><input v-model="search" placeholder="Tìm mã hoặc tên màn hình…" aria-label="Tìm wireframe"><div class="inline"><AppDropdown v-model="group" label="Nhóm màn hình" :options="[{ value: '', label: 'Tất cả nhóm' }, ...['LT','GT','DB','HH','MK']]" /><AppDropdown v-model="device" label="Thiết bị" :options="[{value: '',label: 'Mọi thiết bị'},{value: 'desktop',label: 'Desktop'},{value: 'mobile',label: 'Mobile'}]" /></div><p class="help">{{filtered.length}} màn hình</p><nav aria-label="Danh sách wireframe"><button v-for="s in filtered" :key="s.screenCode" :class="{active:selected===s.screenCode}" @click="selected=s.screenCode"><strong>{{s.screenCode}}</strong><span>{{s.title}}</span><small>{{s.width}} × {{s.height}}</small></button></nav></aside><section class="reference-workspace"><div class="reference-toolbar"><div><strong>{{current?.screenCode}} · {{current?.title}}</strong><p class="help">Bản dựng tọa độ dùng để kiểm tra bố cục; tương tác nghiệp vụ nằm ở website.</p></div><div class="inline"><AppDropdown v-model="mode" label="Chế độ đối chiếu" :options="[{value: 'styled',label: 'Tọa độ + màu DESIGN.md'},{value: 'original',label: 'Ảnh wireframe gốc'},{value: 'raw',label: 'Cấu trúc AST gốc'}]" /><div class="zoom-label">Thu phóng <AppDropdown v-model="zoom" label="Tỉ lệ thu phóng" :options="[.35,.5,.65,.8,1].map(value => ({ value, label: Math.round(value * 100) + '%' }))" /></div></div></div><p v-if="current?.screenCode==='HH-43'" class="notice">HH-43 là sơ đồ tổng quan luồng, không phải một trang website.</p><div v-if="loading" class="skeleton reference-loading"></div><p v-else-if="error" class="notice">{{error}}</p><div v-else-if="data" class="reference-scroll"><div :style="size" class="reference-scale-space"><div :style="{transform:'scale('+zoom+')',width:current.width+'px',transformOrigin:'top left'}"><img v-if="mode==='original'" :src="'/references/'+selected+'.png'" :alt="current.title+' — wireframe gốc'" :style="{width:current.width+'px',marginTop:'-40px'}"><WireframeCanvas v-else :key="selected+'-'+mode" :data="data" :themed="mode==='styled'"/></div></div></div></section></div></template>
